/// An event of the person's input on a shown map, by the `Map` member registering its handler.
enum CruftFreeMapEvent { onClick, onDoubleClick, onPointer, onKey }

/// One registered handler: the owner holding it, its name, the event it hears and what it runs.
class _CruftFreeMapHandler {
  const _CruftFreeMapHandler({required this.owner, required this.name, required this.event, required this.action});

  final Object owner;
  final String name;
  final CruftFreeMapEvent event;
  final FutureOr<void> Function(Object value) action;
}

/// The handlers the owners of one map registered, in the order they were
/// registered. An event runs every handler of it, in that order; one name per
/// owner: registering it again replaces its handler, of whichever event, and
/// the replacement counts as registered now. An owner removes only its own
/// handlers, by name ([off]) or all at once when it is disposed ([release]).
/// Listeners are told when the handlers change.
class CruftFreeMapHandlers extends ChangeNotifier {
  List<_CruftFreeMapHandler> _entries = const <_CruftFreeMapHandler>[];

  /// *owner* registers *action* for *event* as *name*, replacing its handler of that name.
  void on(Object owner, CruftFreeMapEvent event, String name, FutureOr<void> Function(Object value) action) {
    _entries = [
      for (final entry in _entries)
        if (!identical(entry.owner, owner) || entry.name != name) entry,
      _CruftFreeMapHandler(owner: owner, name: name, event: event, action: action),
    ];
    notifyListeners();
  }

  /// *owner*'s handler *name*, of whichever event, is removed; nothing when it holds none.
  void off(Object owner, String name) => _keep((entry) => !identical(entry.owner, owner) || entry.name != name);

  /// Every handler *owner* holds is removed.
  void release(Object owner) => _keep((entry) => !identical(entry.owner, owner));

  /// Whether any handler hears *event*.
  bool listens(CruftFreeMapEvent event) => _entries.any((entry) => entry.event == event);

  /// The person made *event*: every handler of it runs with *value*, in registration order.
  void fire(CruftFreeMapEvent event, Object value) {
    for (final entry in _entries) {
      if (entry.event == event) {
        final ran = entry.action(value);
        if (ran is Future<void>) {
          unawaited(ran);
        }
      }
    }
  }

  void _keep(bool Function(_CruftFreeMapHandler entry) kept) {
    final left = [
      for (final entry in _entries)
        if (kept(entry)) entry,
    ];
    if (left.length != _entries.length) {
      _entries = left;
      notifyListeners();
    }
  }
}

/// One owner's handlers on the maps it names (a page, component, layout or the
/// app state holds its own): `Map.onClick(m, name, ...)` and the other events
/// register under this owner, `Map.off` removes this owner's handler of the
/// name, and the owner's disposal removes every handler it registered on every handle.
class CruftFreeMapEvents {
  final Set<CruftFreeMapHandle> _handles = <CruftFreeMapHandle>{};

  /// `Map.onClick`: *action* runs with the point of each click on the map.
  void onClick(CruftFreeMapHandle handle, String name, FutureOr<void> Function(GeoPoint point) action) => _on(handle, CruftFreeMapEvent.onClick, name, (value) => action(value as GeoPoint));

  /// `Map.onDoubleClick`: *action* runs with the point of each double click on the map.
  void onDoubleClick(CruftFreeMapHandle handle, String name, FutureOr<void> Function(GeoPoint point) action) => _on(handle, CruftFreeMapEvent.onDoubleClick, name, (value) => action(value as GeoPoint));

  /// `Map.onPointer`: *action* runs with the point under the pointer as it moves over the map.
  void onPointer(CruftFreeMapHandle handle, String name, FutureOr<void> Function(GeoPoint point) action) => _on(handle, CruftFreeMapEvent.onPointer, name, (value) => action(value as GeoPoint));

  /// `Map.onKey`: *action* runs with the name of each key pressed while the map has focus.
  void onKey(CruftFreeMapHandle handle, String name, FutureOr<void> Function(String key) action) => _on(handle, CruftFreeMapEvent.onKey, name, (value) => action(value as String));

  /// `Map.off`: removes this owner's handler *name* on the map; nothing when it holds none.
  void off(CruftFreeMapHandle handle, String name) => handle.handlers.off(this, name);

  /// The owner is disposed: every handler it registered is removed.
  void dispose() {
    for (final handle in _handles) {
      handle.handlers.release(this);
    }
    _handles.clear();
  }

  void _on(CruftFreeMapHandle handle, CruftFreeMapEvent event, String name, FutureOr<void> Function(Object value) action) {
    _handles.add(handle);
    handle.handlers.on(this, event, name, action);
  }
}

/// The name a key handler hears for *event*: the character a printable key
/// types (`a`, `1`, ` `), else the key's label without spaces (`Escape`,
/// `Enter`, `ArrowUp`).
String cruftfreeMapKeyName(KeyEvent event) {
  final character = event.character;
  if (character != null && character.isNotEmpty && character.runes.every((rune) => rune >= 0x20 && rune != 0x7f)) {
    return character;
  }
  return event.logicalKey.keyLabel.replaceAll(' ', '');
}

/// A layer as a tap sees it: its name, and whether it takes a click (it runs
/// an `onClick` or opens a `popup`).
abstract interface class CruftFreeMapHitLayer {
  String get name;

  bool get takesClick;
}

/// The layer a tap reached and its feature under the point.
typedef CruftFreeMapHit<L, F> = ({L layer, F feature});

/// The layer a tap reaches: of *layers*, in declared order, asked from last to
/// first (the last declared is drawn on top), the first that takes a click and
/// has a feature under the point (*featureUnder*, `null` for none). A layer
/// taking no click lets the tap through to the ones below; `null` when the tap
/// reaches none.
Future<CruftFreeMapHit<L, F>?> cruftfreeHitLayer<L extends CruftFreeMapHitLayer, F extends Object>(List<L> layers, Future<F?> Function(L layer) featureUnder) async {
  for (final layer in layers.reversed) {
    if (!layer.takesClick) {
      continue;
    }
    final feature = await featureUnder(layer);
    if (feature != null) {
      return (layer: layer, feature: feature);
    }
  }
  return null;
}

/// The one popup a map shows. Opening one replaces the one shown; Escape, back,
/// or a tap anywhere outside it closes it.
class CruftFreeMapPopups<P extends Object> {
  P? _shown;

  /// The popup shown, or `null`.
  P? get shown => _shown;

  /// Shows *popup* in place of any popup shown.
  void open(P popup) {
    _shown = popup;
  }

  void close() {
    _shown = null;
  }

  /// A key pressed anywhere: Escape closes the popup shown. Whether it closed one.
  bool keyPressed(LogicalKeyboardKey key) {
    if (key != LogicalKeyboardKey.escape || _shown == null) {
      return false;
    }
    close();
    return true;
  }

  /// A tap anywhere: one outside the popup shown (*inside* false) closes it.
  void pressed({required bool inside}) {
    if (!inside) {
      close();
    }
  }

  /// Back closes the popup shown. Whether it closed one (and so spent the back).
  bool back() {
    if (_shown == null) {
      return false;
    }
    close();
    return true;
  }
}

/// `layer Name(data: binding) : fill, ...`: the features the style document's
/// source `Name` draws (the binding's loaded value: its [items], each written
/// as GeoJSON by [toFeature]), the state members the document's paint reads,
/// by name, and whether it is shown (a named map's layer: the owner's member
/// `Map.show` writes; any other: always). [onActivate] is its `onClick`, run
/// with the tapped feature, and [popup] builds its `popup` view of it.
class CruftFreeMapLayer<F> extends CruftFreeMapContent implements CruftFreeMapHitLayer {
  const CruftFreeMapLayer({required this.name, required this.items, required this.toFeature, this.state = const <String, Object>{}, this.visible = true, this.onActivate, this.popup});

  @override
  final String name;
  final List<F> items;
  final Map<String, Object?> Function(F item) toFeature;
  final Map<String, Object> state;
  final bool visible;
  final ValueChanged<F>? onActivate;
  final Widget Function(F item)? popup;

  @override
  bool get takesClick => onActivate != null || popup != null;

  bool get hasPopup => popup != null;

  /// The GeoJSON features drawn, each carrying its position in [items].
  List<Map<String, Object?>> get features => [for (final (index, item) in items.indexed) _withFeatureIndex(toFeature(item), index)];

  /// The GeoJSON geometry type of each feature drawn, in [items]' order; `''` for a feature with none, which no kind draws.
  List<String> get geometryTypes => [
    for (final item in items)
      if (toFeature(item)['geometry'] case {'type': final String type}) type else '',
  ];

  /// A tap reached its feature at *index*: runs its `onClick` with that feature.
  void activateAt(int index) => onActivate?.call(items[index]);

  /// Its `popup` view of the feature at *index*.
  Widget popupAt(int index) {
    final build = popup;
    if (build == null) {
      throw StateError('Map layer $name has no popup.');
    }
    return build(items[index]);
  }
}

/// *feature* with its position *index* among its layer's items in its properties.
Map<String, Object?> _withFeatureIndex(Map<String, Object?> feature, int index) {
  final properties = feature['properties'];
  return {
    ...feature,
    'properties': {if (properties != null) ..._object(properties, 'The properties of a map feature'), _featureIndex: index},
  };
}

