  /// The zoom the camera stands at, or `null` before the engine reports one.
  double? zoomLevel();

  /// The GeoJSON geometry type of each feature the layer declared as *layer*
  /// draws, in the order its binding loaded them (`''` for a feature with
  /// none); `null` while the map draws no such layer.
  List<String>? layerGeometryTypes(String layer);

  /// The colour scheme the map is shown in: the theme brightness's name.
  String? schemeShown();

  /// The handle's sketch changed: the map draws it again.
  void sketched();
}

