/// What a layer's data binding reports: a read in flight, its latest failure, and re-running it.
class CruftFreeMapLayerRead {
  const CruftFreeMapLayerRead({required this.isLoading, required this.error, required this.site, required this.refresh});

  /// What *binding* reports now.
  factory CruftFreeMapLayerRead.of(SyncedBinding binding) => CruftFreeMapLayerRead(isLoading: binding.isLoading, error: binding.error, site: binding.site, refresh: binding.refresh);

  final bool isLoading;
  final CruftFreeException? error;
  final ReadSite? site;
  final Future<void> Function() refresh;
}

/// What `Map.filter` filters a layer by: its `colorBy`.
class CruftFreeMapColorBy {
  const CruftFreeMapColorBy({required this.value, required this.members});

  /// The expression reading the property its accessor reads (`['get', 'zone']`).
  final List<Object?> value;

  /// The wire value of every member of the enum it reads, in the enum's order.
  final List<String> members;
}

/// The filter drawing only the features whose `colorBy` value is no member
/// *colorBy* hides: those not in *kept*. `null` while every member is kept. A
/// feature whose value is no member of the enum is drawn whatever is hidden.
List<Object?>? cruftfreeMemberFilter(CruftFreeMapColorBy colorBy, List<String> kept) {
  final hidden = [
    for (final member in colorBy.members)
      if (!kept.contains(member)) member,
  ];
  if (hidden.isEmpty) {
    return null;
  }
  return [
    '!',
    [
      'in',
      colorBy.value,
      ['literal', hidden],
    ],
  ];
}

/// A style layer's own filter *base* (its geometry filter) with a layer's
/// *member* filter: a feature passes both.
List<Object?> cruftfreeFiltered(List<Object?> base, List<Object?>? member) => member == null ? base : ['all', base, member];

/// One layer of the map as the owner declares it to the handle.
class CruftFreeMapLayerDeclaration {
  const CruftFreeMapLayerDeclaration({required this.name, required this.labelKey, required this.groupKey, required this.kind, required this.minZoom, required this.maxZoom, required this.swatches, required this.colorBy, required this.visible, required this.show, required this.read});

  final String name;
  final String labelKey;
  final String? groupKey;

  /// The geometry kind it draws (`fill`, `line`, `circle`, `symbol`).
  final String kind;
  final int? minZoom;
  final int? maxZoom;
  final List<CruftFreeMapSwatchDeclaration> swatches;

  /// Its `colorBy`, or `null` for a layer coloured by none (which `Map.filter` never names).
  final CruftFreeMapColorBy? colorBy;

  /// Reads and writes the owner's member holding whether it is shown.
  final bool Function() visible;
  final ValueChanged<bool> show;

  /// Its data binding, or `null` for a layer drawing a value no binding reads.
  final CruftFreeMapLayerRead Function()? read;
}

/// What the handle words and counts its layers' state with: the session's
/// text and locale, the derived text of a failed read, and the app's
/// `skippedFeatures` and `keptMembers`.
class CruftFreeMapLayerContext {
  const CruftFreeMapLayerContext({required this.key, required this.locale, required this.errorText, required this.skippedFeatures, required this.keptMembers});

  final Message Function(String messageKey) key;
  final String Function() locale;
  final String Function(CruftFreeException failure, ReadSite? site) errorText;
  final int Function(List<String> geometryTypes, String kind) skippedFeatures;

  /// The members a layer keeps drawing once *member* is *shown* or hidden, *kept* those drawn before.
  final List<String> Function(List<String> members, List<String> kept, String member, bool shown) keptMembers;
}

/// The context an owner's map handle reads in: the session's text and locale,
/// and the app's *skippedFeatures* and *keptMembers*.
CruftFreeMapLayerContext cruftfreeMapLayerContext(int Function(List<String> geometryTypes, String kind) skippedFeatures, List<String> Function(List<String> members, List<String> kept, String member, bool shown) keptMembers) => CruftFreeMapLayerContext(key: (messageKey) => cruftfreeRuntime.messages.key(messageKey), locale: () => cruftfreeRuntime.session.locale, errorText: (failure, site) => cruftfreeLayerErrorText(failure, site, cruftfreeRuntime.messages), skippedFeatures: skippedFeatures, keptMembers: keptMembers);

/// The derived text of a failed read: the app's wording for the failure
/// (`readFailed.<kind>`), else the problem's title, else -- a failure no
/// problem describes -- the framework's failure text. Never the problem's
/// detail, which a server writes for its own logs.
String cruftfreeLayerErrorText(CruftFreeException failure, ReadSite? site, Messages messages) {
  final problem = failure.problem;
  final worded = readFailureText(problem ?? ProblemDetails.decode(null, ProblemDetails.noResponseStatus, null), messages, site);
  return worded ?? (problem == null ? messages.key(failedLabelKey).text : problemTitleText(problem, messages));
}

/// Whether a map at *zoom* is outside the zoom range from *minZoom* to below
/// *maxZoom*, so the layer neither loads nor draws.
bool cruftfreeZoomGated(double? zoom, int? minZoom, int? maxZoom) {
  if (zoom == null) {
    return false;
  }
  return (minZoom != null && zoom < minZoom) || (maxZoom != null && zoom >= maxZoom);
}

/// What the attached map draws, as the handle last read it.
class _CruftFreeDrawn {
  const _CruftFreeDrawn({required this.zoom, required this.geometryTypes, required this.scheme});

  static const _CruftFreeDrawn none = _CruftFreeDrawn(zoom: null, geometryTypes: <String, List<String>>{}, scheme: null);

  final double? zoom;
  final Map<String, List<String>> geometryTypes;
  final String? scheme;
}

/// Whether *a* and *b* hold the same geometry types per layer.
bool _sameGeometry(Map<String, List<String>> a, Map<String, List<String>> b) {
  if (a.length != b.length) {
    return false;
  }
  for (final MapEntry(key: layer, value: types) in a.entries) {
    final other = b[layer];
    if (other == null || other.length != types.length) {
      return false;
    }
    for (var index = 0; index < types.length; index++) {
      if (types[index] != other[index]) {
        return false;
      }
    }
  }
  return true;
}

/// The handle a view names for one map it shows (`map : ref(fleet)`): the page
/// or component owns it, the map attaches its camera to it. `Map.fit` and
/// `Map.flyTo` move the camera; `Map.show(fleet, Zones, visible)` writes the
/// owner's member holding whether the layer is shown. A handle whose map is not
/// shown (not built yet, or gone) moves nothing, and still writes its layers'
/// members.
///
/// `fleet.layers` lists each layer's state, in declared order: what its
/// declaration decides (its label, group and legend swatches), whether it is
/// shown, and what its data binding and its map report -- a read in flight,
/// the derived text of its latest failed read (never a problem's detail), the
/// features it draws and those its kind skips (the app's `skippedFeatures`),
/// and whether the map's zoom is outside the layer's zoom range.
/// `fleet.reload(Zones)` re-runs the layer's binding. The owner listens to the
/// handle: it is told when what the map draws changes a layer's state. A
/// handle passes to a component's `MapHandle` parameter as itself.
class CruftFreeMapHandle extends ChangeNotifier {
  /// *context*: the owner's text and the app's `skippedFeatures`; *layers*:
  /// each named layer of the map, in declared order.
  CruftFreeMapHandle({required this.context, required List<CruftFreeMapLayerDeclaration> layers}) : _declared = layers, _byName = {for (final layer in layers) layer.name: layer}, _kept = {for (final layer in layers) layer.name: ?layer.colorBy?.members} {
    // A change of the handlers tells the owner, so its map stops zooming on a double tap a handler hears.
    handlers.addListener(notifyListeners);
  }

  /// What the handle words and counts its layers' state with.
  final CruftFreeMapLayerContext context;

  /// The handlers the owners registered on the map (`Map.onClick`, ...); the map hands each event to them.
  final CruftFreeMapHandlers handlers = CruftFreeMapHandlers();

  /// The geometry `Map.sketch` drew last, as GeoJSON; `null` for none.
  Map<String, Object?>? _sketch;
  final List<CruftFreeMapLayerDeclaration> _declared;
  final Map<String, CruftFreeMapLayerDeclaration> _byName;

  /// The `colorBy` members each layer coloured by one draws, every one at first.
  final Map<String, List<String>> _kept;
  CruftFreeMapCommands? _attached;
  _CruftFreeDrawn _drawn = _CruftFreeDrawn.none;

  /// Each text key resolved in the locale it was resolved in: two layers
  /// naming one group hold the same `Message` -- the one a panel lists the
  /// group by -- for as long as the locale holds.
  final Map<String, Message> _texts = {};
  String? _textsLocale;

  /// Each layer's state, in declared order.
  List<CruftFreeMapLayerState> get layers => [for (final layer in _declared) _stateOf(layer)];

  /// Moves the camera so it shows *bounds*.
  void fit(GeoBounds bounds) => _attached?.fit(bounds);

  /// Flies the camera to *point* at *zoom*.
  void flyTo(GeoPoint point, num zoom) => _attached?.flyTo(point, zoom);

  /// `Map.basemap`: switches the map to the basemap *name*, one of its `basemaps(...)`.
  void basemap(String name) => _attached?.basemap(name);

  /// `Map.sketch`: draws *geometry* into the map's sketch source; `null` clears the sketch.
  void sketch(Object? geometry) {
    _sketch = geometry == null ? null : _object(jsonDecode(jsonEncode(geometry)), 'A sketched geometry');
    _attached?.sketched();
  }

  /// The geometry the map's sketch source draws, as GeoJSON; `null` for none.
  Map<String, Object?>? get sketched => _sketch;

  /// The zoom the shown map's camera stands at; `null` while no map is shown
  /// under the handle, or before its engine reports one.
  double? get zoom => _drawn.zoom;

  /// Shows or hides the layer the map declares as *layer*.
  void show(String layer, bool visible) => _named(layer).show(visible);

  /// Re-runs the data binding of the layer the map declares as *layer*; nothing for a layer no binding reads.
  void reload(String layer) {
    final read = _named(layer).read;
    if (read != null) {
      unawaited(read().refresh());
    }
  }

  /// `Map.filter`: hides (*shown* false) or shows the features of the layer
  /// declared as *layer* whose `colorBy` value is *member*. Only what the map
  /// draws changes: no read is re-run.
  void filter(String layer, String member, bool shown) {
    final colorBy = _colorByOf(layer);
    if (!colorBy.members.contains(member)) {
      throw StateError('Layer $layer is coloured by the members ${colorBy.members.join(', ')}, not $member.');
    }
    final before = keptMembers(layer);
    final after = context.keptMembers(List<String>.of(colorBy.members), List<String>.of(before), member, shown);
    if (after.length == before.length && after.every(before.contains)) {
      return;
    }
    _kept[layer] = List<String>.unmodifiable(after);
    notifyListeners();
  }

  /// The `colorBy` members the layer declared as *layer* draws, in the enum's order.
  List<String> keptMembers(String layer) {
    _colorByOf(layer);
    final kept = _kept[layer];
    if (kept == null) {
      throw StateError('Layer $layer is coloured by an enum, yet the handle keeps no members of it.');
    }
    return kept;
  }

  /// The member filter the map draws the layer declared as *layer* with;
  /// `null` while it hides no member, is coloured by none, or is declared to
  /// the handle by no layer (the map asks for every layer it draws).
  List<Object?>? memberFilter(String layer) {
    final colorBy = _byName[layer]?.colorBy;
    return colorBy == null ? null : cruftfreeMemberFilter(colorBy, keptMembers(layer));
  }

  CruftFreeMapColorBy _colorByOf(String layer) {
    final colorBy = _named(layer).colorBy;
    if (colorBy == null) {
      throw StateError('Layer $layer is coloured by no enum, so no member of it can be filtered.');
    }
    return colorBy;
  }

  /// Called by the map once it is built.
  void attach(CruftFreeMapCommands map) {
    _attached = map;
    _drawn = _read(map);
    notifyListeners();
  }

  /// Called by the map when what it draws, its zoom or its scheme may have
  /// changed; the owner is told only when a layer's state or the [zoom] did.
  void drawn(CruftFreeMapCommands map) {
    if (!identical(_attached, map)) {
      return;
    }
    final before = _drawn;
    _drawn = _read(map);
    if (before.zoom != _drawn.zoom || before.scheme != _drawn.scheme || !_sameGeometry(before.geometryTypes, _drawn.geometryTypes)) {
      notifyListeners();
    }
  }

  /// Called by the map when it goes away; a newer map is left in place.
  void detach(CruftFreeMapCommands map) {
    if (identical(_attached, map)) {
      _attached = null;
      _drawn = _CruftFreeDrawn.none;
      notifyListeners();
    }
  }

  CruftFreeMapLayerDeclaration _named(String layer) {
    final declared = _byName[layer];
    if (declared == null) {
      throw StateError('The map has no layer $layer; its layers: ${_byName.keys.join(', ')}.');
    }
    return declared;
  }

  _CruftFreeDrawn _read(CruftFreeMapCommands map) => _CruftFreeDrawn(zoom: map.zoomLevel(), geometryTypes: {for (final layer in _declared) layer.name: ?map.layerGeometryTypes(layer.name)}, scheme: map.schemeShown());

  Message _text(String messageKey) {
    final locale = context.locale();
    if (locale != _textsLocale) {
      _texts.clear();
      _textsLocale = locale;
    }
    return _texts.putIfAbsent(messageKey, () => context.key(messageKey));
  }

  CruftFreeMapLayerState _stateOf(CruftFreeMapLayerDeclaration layer) {
    final read = layer.read?.call();
    final failure = read?.error;
    final geometryTypes = _drawn.geometryTypes[layer.name] ?? const <String>[];
    final skipped = context.skippedFeatures(geometryTypes, layer.kind);
    final groupKey = layer.groupKey;
    return CruftFreeMapLayerState(
      name: layer.name,
      label: _text(layer.labelKey),
      group: groupKey == null ? null : _text(groupKey),
      visible: layer.visible(),
      isLoading: read?.isLoading ?? false,
      error: failure == null ? null : Message(text: context.errorText(failure, read?.site)),
      count: geometryTypes.length - skipped,
      skipped: skipped,
      zoomGated: cruftfreeZoomGated(_drawn.zoom, layer.minZoom, layer.maxZoom),
      swatches: [for (final swatch in layer.swatches) CruftFreeLayerSwatch(label: _text(swatch.labelKey), color: _colorOf(swatch))],
    );
  }

  /// *swatch*'s colour in the scheme the map is shown in, else in the scheme shown when none matches.
  String _colorOf(CruftFreeMapSwatchDeclaration swatch) {
    final scheme = _drawn.scheme;
    for (final color in swatch.colors) {
      if (color.scheme == scheme) {
        return color.color;
      }
    }
    for (final color in swatch.colors) {
      if (color.fallback) {
        return color.color;
      }
    }
    throw StateError('A legend swatch of ${swatch.labelKey} names no colour shown when no scheme matches.');
  }
}

/// The paint properties one style layer takes from state, as the engine sets
/// them: only these properties, every other one left as the document set it.
class _StatePaint implements maplibre.LayerProperties {
  const _StatePaint(this.values);

  final Map<String, Object> values;

  @override
  Map<String, dynamic> toJson({bool skipNulls = true}) => Map<String, dynamic>.of(values);
}

/// *color* as the style document's `#rrggbb`.
String _hex(Color color) => '#${(color.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';

Map<String, Object?> _featureCollection(List<Map<String, Object?>> features) => {'type': 'FeatureCollection', 'features': features};

/// *value* as a JSON object, or a [StateError] naming *what* it is.
Map<String, Object?> _object(Object? value, String what) {
  if (value is! Map) {
    throw StateError('$what is not a JSON object: $value');
  }
  return Map<String, Object?>.of(value.cast<String, Object?>());
}

/// The style document *text* holds, checked to be one this adapter applies.
Map<String, Object?> _decodeDocument(String text, String asset) {
  final document = _object(jsonDecode(text), 'The map style document $asset');
  if (document['version'] != _styleVersion) {
    throw StateError('The map style document $asset is version ${document['version']}, not $_styleVersion.');
  }
  _object(document['sources'], 'The sources of the map style document $asset');
  if (document['layers'] is! List) {
    throw StateError('The map style document $asset carries no layer list.');
  }
  return document;
}

/// Why the merge refused a document ([CruftFreeMapStyleMergeError.reason]).
abstract final class CruftFreeMapMergeRefused {
  static const String shape = 'shape';
  static const String version = 'version';
  static const String reservedId = 'reserved_id';
  static const String idClash = 'id_clash';
  static const String unconfiguredOverlay = 'unconfigured_overlay';
}

/// A basemap document, or a map's own, the merge refuses: [reason] says why
/// (one of [CruftFreeMapMergeRefused]).
class CruftFreeMapStyleMergeError implements Exception {
  const CruftFreeMapStyleMergeError(this.reason, this.message);

  final String reason;
  final String message;

  @override
  String toString() => 'CruftFreeMapStyleMergeError($reason): $message';
}

/// A profile's map addresses as its runtime config carries them: what the merge reads.
class CruftFreeMapAddresses {
  const CruftFreeMapAddresses({required this.tiles, required this.attribution, required this.glyphs, required this.overlays});

  /// `map.tiles`: the raster tiles drawn when the map shows no basemap.
  final String tiles;
  final String attribution;

  /// `map.glyphs`, when configured: the glyphs every text layer of the merged style reads.
  final String? glyphs;

  /// `maps.overlays`: entry name to raster tile address.
  final Map<String, String> overlays;
}

/// A style document's sources and layers, copied.
typedef _CruftFreeStyleParts = ({Map<String, Object?> sources, List<Map<String, Object?>> layers});

/// A deep copy of the JSON value *value*.
Object? _copied(Object? value) => jsonDecode(jsonEncode(value));

/// A copy of *document*'s sources and layers, refused unless it is a version
/// [_styleVersion] style with a source object and a layer list of layers with ids.
_CruftFreeStyleParts _stylePartsOf(Map<String, Object?> document, String what) {
  if (document['version'] != _styleVersion) {
    throw CruftFreeMapStyleMergeError(CruftFreeMapMergeRefused.version, '$what is style version ${document['version']}; the map engine reads version $_styleVersion.');
  }
  final sources = document['sources'];
  final layers = document['layers'];
  if (sources is! Map || layers is! List || !layers.every((layer) => layer is Map && layer['id'] is String)) {
    throw CruftFreeMapStyleMergeError(CruftFreeMapMergeRefused.shape, "$what holds no 'sources' object and 'layers' list of layers with ids.");
  }
  return (sources: _object(_copied(sources), '$what\'s sources'), layers: [for (final layer in layers) _object(_copied(layer), 'A layer of $what')]);
}

List<String> _layerIds(List<Map<String, Object?>> layers) => [for (final layer in layers) layer['id'] as String];

/// Refuses a basemap id the adapter reserves, or one the map's document
/// declares: the merge would draw the wrong source, or shadow a layer.
void _refuseBasemapIds(_CruftFreeStyleParts base, _CruftFreeStyleParts app) {
  final baseLayerIds = _layerIds(base.layers);
  final reserved = {...base.sources.keys, ...baseLayerIds}.where((id) => id.startsWith(_reservedIdPrefix)).toList()..sort();
  if (reserved.isNotEmpty) {
    throw CruftFreeMapStyleMergeError(CruftFreeMapMergeRefused.reservedId, "A basemap document declares the id(s) ${reserved.join(', ')}, which the map adapter reserves (prefix '$_reservedIdPrefix').");
  }
  final appLayerIds = _layerIds(app.layers).toSet();
  final clashes = {...base.sources.keys.where(app.sources.containsKey), ...baseLayerIds.where(appLayerIds.contains)}.toList()..sort();
  if (clashes.isNotEmpty) {
    throw CruftFreeMapStyleMergeError(CruftFreeMapMergeRefused.idClash, "A basemap document declares the id(s) ${clashes.join(', ')}, which a layer or overlay of the map declares; a merged style holds each id once.");
  }
}

/// Gives the source of *layer*, when it is an overlay's, the tiles its profile
/// entry names; refused when the profile configures no such entry.
void _addressOverlay(Map<String, Object?> layer, Map<String, Object?> sources, CruftFreeMapAddresses addresses) {
  final metadata = layer['metadata'];
  final described = metadata is Map ? metadata[_overlayMetadataKey] : null;
  if (described is! Map) {
    return;
  }
  final entry = described[_overlayAddressKey];
  final address = entry is String ? addresses.overlays[entry] : null;
  final sourceId = layer['source'];
  final source = sourceId is String ? sources[sourceId] : null;
  if (sourceId is! String || address == null || source is! Map) {
    final configured = addresses.overlays.keys.toList()..sort();
    throw CruftFreeMapStyleMergeError(CruftFreeMapMergeRefused.unconfiguredOverlay, "Overlay '${layer['id']}' loads its tiles from '$entry', which is no source of the map or no entry of the profile's maps overlays ${configured.join(', ')}.");
  }
  sources[sourceId] = {
    ...source.cast<String, Object?>(),
    'tiles': [address],
  };
}

/// The style a map shows: *basemap*'s sources and layers (its camera keys
/// dropped), or with no basemap the configured raster base; then every source
/// and layer of the map's *document*, in order, each overlay's source given the
/// tiles its profile entry names. The profile's glyphs, when configured,
/// replace a basemap's. CruftFree's one merge rule, which the shared merge table
/// holds every target to; one path loads the whole style, so a switch keeps
/// every layer and overlay.
Map<String, Object?> cruftfreeMergeMapStyle(Map<String, Object?>? basemap, Map<String, Object?> document, CruftFreeMapAddresses addresses) {
  final app = _stylePartsOf(document, "The map's document");
  final Map<String, Object?> merged;
  final Map<String, Object?> sources;
  final List<Map<String, Object?>> layers;
  if (basemap == null) {
    merged = <String, Object?>{'version': _styleVersion};
    sources = <String, Object?>{
      _baseSource: {
        'type': 'raster',
        'tiles': [addresses.tiles],
        'tileSize': _rasterTileSize,
        'attribution': addresses.attribution,
      },
    };
    layers = [
      {'id': _baseSource, 'type': 'raster', 'source': _baseSource},
    ];
  } else {
    final base = _stylePartsOf(basemap, 'A basemap document');
    _refuseBasemapIds(base, app);
    merged = <String, Object?>{
      for (final MapEntry(:key, :value) in basemap.entries)
        if (!_basemapCameraKeys.contains(key)) key: _copied(value),
    };
    sources = base.sources;
    layers = base.layers;
  }
  sources.addAll(app.sources);
  for (final layer in app.layers) {
    _addressOverlay(layer, sources, addresses);
    layers.add(layer);
  }
  merged['sources'] = sources;
  merged['layers'] = layers;
  final glyphs = addresses.glyphs;
  if (glyphs != null) {
    merged['glyphs'] = glyphs;
  }
  return merged;
}

/// A basemap a map switched to: its word, its style document -- fetched from its
/// `maps.basemaps` address, or read from an installed package -- what it was
/// loaded for ([token]: another key of a package basemap loads it again), and
/// whether it is a package's, whose text is drawn from the package's own glyphs.
class _CruftFreeBasemap {
  const _CruftFreeBasemap(this.name, this.document, this.token, {required this.packaged});

  final String name;
  final Map<String, Object?> document;
  final String token;
  final bool packaged;
}

/// The session's bearer token on the map engines' own requests. The engine
/// holds one set of request headers for every map of the app, so one holder
/// serves every map shown: while one is, it hands each the headers and the
/// anchored address pattern of the API origin ([tileHeaders]) whenever the
/// session changes and when the token is due for renewal, and none (no header,
/// no pattern) once the session ends. When the last map goes away the headers
/// are cleared through it, so no token stays with the engine while no map is
/// shown. An app signing no one in sets no header at all.
class _CruftFreeTileCredential {
  _CruftFreeTileCredential._();

  static final _CruftFreeTileCredential shared = _CruftFreeTileCredential._();

  /// Each map shown, with what it does once its engine first carries the token.
  final Map<maplibre.MapLibreMapController, VoidCallback> _maps = {};

  /// The maps whose engine was last handed the token.
  final Set<maplibre.MapLibreMapController> _carrying = {};

  /// Bumped by every change: a hand-over the next one overtook sets nothing.
  int _turn = 0;
  Timer? _renewal;

  /// *controller*'s map is shown: it is handed the session's headers, and [carried] runs once
  /// its engine first carries the token (its first requests may have gone out without it).
  void attach(maplibre.MapLibreMapController controller, VoidCallback carried) {
    if (cruftfreeRuntime.config.identity == null) {
      return;
    }
    if (_maps.isEmpty) {
      cruftfreeRuntime.session.addListener(_changed);
    }
    _maps[controller] = carried;
    _changed();
  }

  /// *controller*'s map is no longer shown. The last one clears the engine's headers.
  void detach(maplibre.MapLibreMapController controller) {
    if (_maps.remove(controller) == null) {
      return;
    }
    _carrying.remove(controller);
    if (_maps.isNotEmpty) {
      return;
    }
    cruftfreeRuntime.session.removeListener(_changed);
    _renewal?.cancel();
    _renewal = null;
    _turn += 1;
    final cleared = tileHeaders(cruftfreeRuntime.config.apiBaseUrl.toString(), null);
    unawaited(controller.setCustomHeaders(cleared.headers, cleared.filter));
  }

  void _changed() => unawaited(_handOver());

  /// Hands every map shown the headers of the session as it is now: the token
  /// (renewed first when due) to the API origin, or none once signed out.
  Future<void> _handOver() async {
    final turn = ++_turn;
    final session = cruftfreeRuntime.session;
    final token = await session.accessToken();
    if (turn != _turn || _maps.isEmpty) {
      return;
    }
    final handed = tileHeaders(cruftfreeRuntime.config.apiBaseUrl.toString(), token);
    final carries = handed.headers.isNotEmpty;
    _renewal?.cancel();
    final expires = session.accessTokenExpiresAt;
    _renewal = carries && expires != null ? Timer(expires.difference(DateTime.now().toUtc()), _changed) : null;
    for (final MapEntry(key: controller, value: carried) in _maps.entries.toList()) {
      if (turn != _turn) {
        return;
      }
      final arrives = carries && !_carrying.contains(controller);
      if (carries) {
        _carrying.add(controller);
      } else {
        _carrying.remove(controller);
      }
      await controller.setCustomHeaders(handed.headers, handed.filter);
      if (arrives) {
        carried();
      }
    }
  }
}

/// The paint properties *styleLayer* takes from state, each with the member it
/// is set from. The generated document names only paint properties of the
/// style layer's own kind.
Map<String, String> _statePaintOf(Map<String, Object?> styleLayer) {
  final metadata = styleLayer['metadata'];
  final named = metadata is Map ? metadata[_stateMetadataKey] : null;
  if (named == null) {
    return const <String, String>{};
  }
  return _object(named, 'The state paint of map style layer ${styleLayer['id']}').map((property, member) => MapEntry(property, member as String));
}

/// A state member's value as the engine paints it: a width or an opacity, or a dash pattern.
Object _paintValue(Object value, String layer, String member) {
  if (value is num) {
    return value;
  }
  if (value is List && value.every((part) => part is num)) {
    return List<num>.of(value.cast<num>());
  }
  throw StateError('Map layer $layer paints from $member, whose value is neither a number nor a list of numbers: $value');
}

/// When a map bound to a camera state member writes it: [delay] after its
/// camera stops moving, and only when [signature] of the settled camera differs
/// from the signature of the camera the member then holds ([held]). A settle
/// within the signature's rounding writes nothing, and a settle before the wait
/// runs out replaces the one waiting.
class CruftFreeCameraSettle {
  CruftFreeCameraSettle({required this.delay, required this.signature, required this.held, required this.write});

  final Duration delay;
  final String Function(MapCamera camera) signature;
  final MapCamera Function() held;
  final void Function(MapCamera camera) write;
  Timer? _waiting;

  /// The camera stopped moving at *camera*.
  void settled(MapCamera camera) {
    cancel();
    _waiting = Timer(delay, () {
      _waiting = null;
      if (signature(camera) != signature(held())) {
        write(camera);
      }
    });
  }

  void cancel() {
    _waiting?.cancel();
    _waiting = null;
  }
}

/// The pin of a map bound to a `GeoPoint?` member. A click places it at the
/// clicked point and writes the member ([write]); a drag moves it and writes
/// nothing; the drop writes the member where the pin lies, unless that is where
/// the member already stands. A body write of the member ([held]) moves it, a
/// null removing it, and writes nothing back. [show] draws the pin wherever it
/// stands, `null` for none.
class CruftFreeMapPin {
  CruftFreeMapPin({required this.write, required this.show});

  final void Function(GeoPoint point) write;
  final void Function(GeoPoint? point) show;
  GeoPoint? _value;
  GeoPoint? _drawn;

  /// Where the pin is drawn, or `null` for no pin.
  GeoPoint? get marker => _drawn;

  /// The member holds *point*. Its own last write, handed back, changes nothing.
  void held(GeoPoint? point) {
    if (identical(point, _value)) {
      return;
    }
    _value = point;
    _place(point);
  }

  /// The person clicked the map at *point*.
  void clicked(GeoPoint point) {
    _value = point;
    _place(point);
    write(point);
  }

  /// The person dragged the pin to *point*, not yet released.
  void dragged(GeoPoint point) {
    _require('drag');
    _place(point);
  }

  /// The person released the pin they dragged.
  void dropped() {
    final drawn = _require('drop');
    if (drawn == _value) {
      return;
    }
    _value = drawn;
    write(drawn);
  }

  void _place(GeoPoint? point) {
    _drawn = point;
    show(point);
  }

  GeoPoint _require(String action) {
    final drawn = _drawn;
    if (drawn == null) {
      throw StateError('A $action with no pin drawn has nothing to move.');
    }
    return drawn;
  }
}

class CruftFreeMap extends StatefulWidget {
  const CruftFreeMap({super.key, this.center, this.zoom, this.style, this.styles = const <CruftFreeMapStyleScheme>[], this.basemaps = const <String>[], this.packageBasemaps = const <CruftFreePackageBasemap>[], this.packageReader, this.camera, this.cameraSignature, this.settleDelayMs = 0, this.onCameraChanged, this.handle, this.placesPin = false, this.pin, this.onPinChanged, this.onChange, required this.children});

  final CruftFreeMapPoint? center;
  final num? zoom;
  final CruftFreeStyle? style;

  /// The style documents of the map's layers, one per scheme; empty for a map drawing none.
  final List<CruftFreeMapStyleScheme> styles;

  /// The basemaps the map switches between (`basemaps(configured(street), ...)`), by their
  /// `maps.basemaps` names: the first is shown at first. Empty for a map showing the configured
  /// base tiles.
  final List<String> basemaps;

  /// The map's `offline(Package, key, "style")` basemaps, each listed in [basemaps] by its
  /// package's name: their styles are read from the installed copy, never fetched.
  final List<CruftFreePackageBasemap> packageBasemaps;

  /// What reads the app's installed packages; `null` for a map listing none.
  final CruftFreePackageReader? packageReader;

  /// The camera state member the map stands at (`camera(...)`); `null` for a map fitting its content.
  final MapCamera? camera;

  /// The app's `cameraSignature`, which a settled camera must change for the member to be written.
  final String Function(MapCamera camera)? cameraSignature;

  /// How long after the camera stops moving the member is written, in milliseconds.
  final int settleDelayMs;

  /// Writes the member: the settled camera, each time its signature changed.
  final ValueChanged<MapCamera>? onCameraChanged;

  /// The owner's handle naming this map (`ref(...)`), which the map moves by; `null` for an unnamed map.
  final CruftFreeMapHandle? handle;

  /// Whether the map is bound to a `GeoPoint?` member (`bind(...)`), which it shows as a draggable pin.
  final bool placesPin;

  /// The point the bound member holds, `null` for none.
  final GeoPoint? pin;

  /// Writes the member: the point the person placed the pin at.
  final ValueChanged<GeoPoint>? onPinChanged;

  /// The map's `onChange`, run after each write the person makes.
  final VoidCallback? onChange;
  final List<CruftFreeMapContent> children;

  @override
  State<CruftFreeMap> createState() => _CruftFreeMapState();
}

class _CruftFreeMapState extends State<CruftFreeMap> implements CruftFreeMapCommands {
  maplibre.MapLibreMapController? _controller;

  /// The document the engine was created with, and what the shown style was
  /// built from: the scheme's document and the theme's colours.
  String? _initialStyle;
  String? _shownKey;
  bool _styleLoaded = false;

  /// The style last set on the engine, and its overlays' areas as text: another area sets the style again.
  String? _shownStyle;
  String? _shownBounds;

  /// The scheme shown, and its document once loaded.
  CruftFreeMapStyleScheme? _scheme;
  Map<String, Object?>? _document;

  /// The basemap `Map.basemap` last asked for; `null` until it does (the first listed is shown).
  String? _basemapAsked;

  /// The basemap whose document loaded last, with the document; `null` while none has.
  _CruftFreeBasemap? _basemapLoaded;

  /// What the basemap being loaded is loaded for ([_basemapToken]), `null` for none.
  String? _basemapFetching;

  /// The camera the map stands at, as the member last held it: any other value moves the map.
  MapCamera? _placed;
  CruftFreeCameraSettle? _settle;

  /// The popup shown, and where on the drawing it stands (`null` until placed).
  final CruftFreeMapPopups<_CruftFreeOpenPopup> _popups = CruftFreeMapPopups<_CruftFreeOpenPopup>();
  Offset? _popupOffset;

  /// The zoom the camera last stood at when it stopped, and the theme's brightness, as the handle reads them.
  double? _zoom;
  Brightness? _brightness;

  /// The pin rule of a map bound to a `GeoPoint?` member, the circle drawing
  /// its pin, and the engine updates of that circle, run one after another.
  CruftFreeMapPin? _pin;
  maplibre.Circle? _pinCircle;
  Future<void> _pinDrawing = Future<void>.value();

  /// The focus the map holds once tapped, which the key handlers hear through.
  final FocusNode _focus = FocusNode(debugLabel: 'CruftFreeMap');

  /// When and where the last tap landed, by which a second one soon after and close by is a double tap.
  final Stopwatch _tapClock = Stopwatch()..start();
  ({Duration at, Point<double> point})? _lastTap;

  List<CruftFreeMapMarker> get _markers => widget.children.whereType<CruftFreeMapMarker>().toList();
  List<CruftFreeMapPolyline> get _polylines => widget.children.whereType<CruftFreeMapPolyline>().toList();
  List<CruftFreeMapRing> get _rings => widget.children.whereType<CruftFreeMapRing>().toList();
  List<CruftFreeMapLayer<Object?>> get _layers => widget.children.whereType<CruftFreeMapLayer<Object?>>().toList();
  List<CruftFreeMapOverlay> get _overlays => widget.children.whereType<CruftFreeMapOverlay>().toList();

  /// Whether a layer of this map opens a popup, which follows the camera as it moves.
  bool get _showsPopups => _layers.any((layer) => layer.hasPopup);

  MapRuntimeConfig _mapConfig() {
    final config = cruftfreeRuntime.config.map;
    if (config == null) {
      throw StateError('This app draws a map, so its runtime config must carry the map block.');
    }
    return config;
  }

  /// The scheme the theme's *brightness* names, else the one shown when none
  /// does; `null` for a map drawing no layer.
  CruftFreeMapStyleScheme? _preferredScheme(Brightness brightness) {
    final styles = widget.styles;
    if (styles.isEmpty) {
      return null;
    }
    for (final scheme in styles) {
      if (scheme.scheme == brightness.name) {
        return scheme;
      }
    }
    for (final scheme in styles) {
      if (scheme.fallback) {
        return scheme;
      }
    }
    throw StateError('A map style names no scheme shown when no other matches the theme.');
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final brightness = Theme.of(context).brightness;
    if (brightness != _brightness) {
      _brightness = brightness;
      widget.handle?.drawn(this);
    }
    _showPreferred();
  }

  /// Show the scheme the theme prefers, loading its bundled document first when it is not the one held.
  void _showPreferred() {
    final scheme = _preferredScheme(Theme.of(context).brightness);
    if (scheme == null) {
      _apply(null, null);
      return;
    }
    if (scheme.asset == _scheme?.asset && _document != null) {
      _apply(scheme, _document);
      return;
    }
    unawaited(_load(scheme, DefaultAssetBundle.of(context)));
  }

  /// Load *scheme*'s bundled document, then apply it while it is still the preferred scheme.
  Future<void> _load(CruftFreeMapStyleScheme scheme, AssetBundle bundle) async {
    final document = _decodeDocument(await bundle.loadString(scheme.asset), scheme.asset);
    if (!mounted) {
      return;
    }
    if (_preferredScheme(Theme.of(context).brightness)?.asset != scheme.asset) {
      return;
    }
    setState(() => _apply(scheme, document));
  }

  /// Show *document* (of *scheme*) in the theme's colours over the basemap shown, unless that is
  /// what is shown. A map listing basemaps shows nothing until the first one's document has loaded.
  void _apply(CruftFreeMapStyleScheme? scheme, Map<String, Object?>? document) {
    _scheme = scheme;
    _document = document;
    final basemap = _basemapShown();
    if (basemap == null && widget.basemaps.isNotEmpty) {
      // The first basemap's document is loading: the map is drawn once it has.
      return;
    }
    final colors = Theme.of(context).colorScheme;
    final bounds = jsonEncode(_overlayBounds(document));
    final key = '${scheme?.asset}|${basemap?.name}|${_hex(colors.primary)}|${_hex(colors.surface)}|$bounds';
    if (key == _shownKey) {
      return;
    }
    _shownKey = key;
    _shownBounds = bounds;
    final style = _styleOf(_mapConfig(), colors, document, basemap);
    _shownStyle = style;
    _initialStyle ??= style;
    final controller = _controller;
    if (controller != null) {
      // The style is set whole: the base, the map's layers and overlays, its lines and markers.
      // Its data is replayed once the engine has loaded it (`_styleLoadedNow`); nothing is re-added
      // layer by layer.
      _styleLoaded = false;
      unawaited(controller.setStyle(style));
    }
  }

  /// The basemap the map shows: the one asked for once its document has loaded; while a switch
  /// loads, the one shown before it; `null` for a map listing none, and while the first is
  /// loading, which the map waits for rather than drawing tiles it was not asked to draw.
  _CruftFreeBasemap? _basemapShown() {
    final listed = widget.basemaps;
    if (listed.isEmpty) {
      return null;
    }
    final wanted = _basemapAsked ?? listed.first;
    final loaded = _basemapLoaded;
    final token = _basemapToken(wanted);
    if (loaded != null && loaded.token == token) {
      return loaded;
    }
    _fetchBasemap(wanted, token);
    return loaded;
  }

  /// The package basemap the map lists as [name], or `null` for a configured basemap.
  CruftFreePackageBasemap? _packageBasemap(String name) {
    for (final entry in widget.packageBasemaps) {
      if (entry.name == name) {
        return entry;
      }
    }
    return null;
  }

  /// What the basemap [name] is loaded for: its name, and for a package basemap its copy and style.
  String _basemapToken(String name) => _packageBasemap(name)?.token ?? name;

  /// Fetches the style document of the basemap *name* through the runtime's authorized
  /// transport, so its request takes the client's one auth path (the bearer reaches the app's own
  /// API only), or reads a package basemap's from its installed copy. A later switch supersedes a
  /// load in flight; a failed load is raised to the app's error reporting and the map keeps what
  /// it shows.
  void _fetchBasemap(String name, String token) {
    if (_basemapFetching == token) {
      return;
    }
    _basemapFetching = token;
    unawaited(_loadBasemap(name, token));
  }

  Future<void> _loadBasemap(String name, String token) async {
    try {
      final packaged = _packageBasemap(name);
      final Map<String, Object?> document;
      if (packaged == null) {
        final bytes = await cruftfreeRuntime.transport.fetchBytes(Uri.parse(_basemapAddress(name)), accept: 'application/json');
        document = _object(jsonDecode(utf8.decode(bytes)), 'The style document of basemap $name');
      } else {
        final reader = widget.packageReader;
        if (reader == null) {
          throw StateError('This map shows the package basemap $name but is handed no package reader.');
        }
        // A package basemap is read from its installed copy, never fetched.
        document = (await cruftfreeLoadPackageBasemap(reader, packaged, cruftfreeRuntime.store)).document;
      }
      if (!mounted || _basemapFetching != token) {
        return;
      }
      _basemapFetching = null;
      setState(() => _basemapLoaded = _CruftFreeBasemap(name, document, token, packaged: packaged != null));
      _showPreferred();
    } finally {
      if (_basemapFetching == token) {
        _basemapFetching = null;
      }
    }
  }

  /// The style document address the runtime config's `maps.basemaps` gives *name*.
  String _basemapAddress(String name) {
    final address = cruftfreeRuntime.config.maps?.basemaps[name];
    if (address == null) {
      throw StateError("This map shows the basemap $name, which the runtime config's maps.basemaps does not carry.");
    }
    return address;
  }

  /// `Map.basemap`: shows the basemap *name*, one of the map's `basemaps(...)`, once its document has loaded.
  @override
  void basemap(String name) {
    final listed = widget.basemaps;
    if (!listed.contains(name)) {
      throw StateError('This map switches between the basemaps ${listed.isEmpty ? '(none)' : listed.join(', ')}, not $name.');
    }
    _basemapAsked = name;
    _showPreferred();
  }

  /// The profile's map addresses the merge reads: the base tiles, their attribution, the glyphs and the overlays' tiles.
  /// Under a package basemap ([packaged]) the profile's glyphs are not laid over the package's own.
  CruftFreeMapAddresses _addresses(MapRuntimeConfig config, {bool packaged = false}) => CruftFreeMapAddresses(tiles: config.tiles, attribution: config.attribution, glyphs: packaged ? null : config.glyphs, overlays: cruftfreeRuntime.config.maps?.overlays ?? const <String, String>{});

  CruftFreeMapLayer<Object?>? _layerNamed(String name) {
    for (final layer in _layers) {
      if (layer.name == name) {
        return layer;
      }
    }
    return null;
  }

  CruftFreeMapOverlay? _overlayNamed(String name) {
    for (final overlay in _overlays) {
      if (overlay.name == name) {
        return overlay;
      }
    }
    return null;
  }

  /// The area each overlay of *document* that declares `bounds(...)` is drawn
  /// inside, by its source: the `GeoBounds` the overlay passes for the member,
  /// west, south, east, north. An overlay passing `null` has no area and is
  /// drawn everywhere.
  Map<String, List<double>> _overlayBounds(Map<String, Object?>? document) {
    final bounds = <String, List<double>>{};
    if (document == null) {
      return bounds;
    }
    for (final entry in document['layers'] as List) {
      final styleLayer = _object(entry, 'A map style layer');
      final metadata = styleLayer['metadata'];
      final described = metadata is Map ? metadata[_overlayMetadataKey] : null;
      final member = described is Map ? described[_overlayBoundsKey] : null;
      final source = styleLayer['source'];
      if (member is! String || source is! String) {
        continue;
      }
      final overlay = _overlayNamed(source);
      if (overlay == null || !overlay.state.containsKey(member)) {
        throw StateError('Map overlay ${styleLayer['id']} reads its bounds from $member, which no overlay of this map passes.');
      }
      final value = overlay.state[member];
      if (value == null) {
        continue;
      }
      if (value is! GeoBounds) {
        throw StateError('Map overlay ${styleLayer['id']} reads its bounds from $member, which holds no GeoBounds: $value');
      }
      final area = value.toJson();
      bounds[source] = [for (final key in _geoBoundsOrder) (area[key]! as num).toDouble()];
    }
    return bounds;
  }

  /// The style shown: *document* with each layer's current features, state
  /// paint, visibility and filter, merged with *basemap* -- or, with none, the
  /// configured base tiles -- by the one merge rule ([cruftfreeMergeMapStyle]), with
  /// the profile's glyph address when it configures one (a layer drawing text
  /// cannot render without it, UI034); then the map's lines and markers above
  /// it all, painted in *colors*' primary colour.
  String _styleOf(MapRuntimeConfig config, ColorScheme colors, Map<String, Object?>? document, _CruftFreeBasemap? basemap) {
    final primary = _hex(colors.primary);
    final documentSources = document == null ? const <String, Object?>{} : _object(document['sources'], 'A map style document\'s sources');
    final documentLayers = document == null ? const <Object?>[] : document['layers'] as List;
    final bounds = _overlayBounds(document);
    final shown = <String, Object?>{
      'version': _styleVersion,
      'sources': <String, Object?>{
        // An overlay's source is drawn inside the area its `bounds` reads.
        for (final MapEntry(key: name, value: source) in documentSources.entries)
          name: switch ((_layerNamed(name), bounds[name])) {
            (final layer?, _) => {..._object(source, 'Map style source $name'), 'data': _featureCollection(layer.features)},
            (null, final area?) => {..._object(source, 'Map style source $name'), 'bounds': area},
            (null, null) => source,
          },
      },
      'layers': [for (final styleLayer in documentLayers) _withFilter(_withVisibility(_withStatePaint(_object(styleLayer, 'A map style layer'))))],
    };
    final merged = cruftfreeMergeMapStyle(basemap?.document, shown, _addresses(config, packaged: basemap?.packaged ?? false));
    final style = <String, Object?>{
      ...merged,
      'sources': {
        ..._object(merged['sources'], 'The merged style\'s sources'),
        _linesSource: {'type': 'geojson', 'data': _featureCollection(_lineFeatures())},
        _ringsSource: {'type': 'geojson', 'data': _featureCollection(_ringFeatures())},
        _sketchSource: {'type': 'geojson', 'data': _featureCollection(_sketchFeatures())},
        _markersSource: {'type': 'geojson', 'data': _featureCollection(_markerFeatures())},
      },
      'layers': [
        ...merged['layers'] as List,
        {
          'id': _linesSource,
          'type': 'line',
          'source': _linesSource,
          'paint': {'line-color': primary, 'line-width': 3},
        },
        ..._inputLayers,
        {
          'id': _markersSource,
          'type': 'circle',
          'source': _markersSource,
          'paint': {'circle-color': primary, 'circle-radius': 8, 'circle-stroke-color': _hex(colors.surface), 'circle-stroke-width': 2},
        },
      ],
    };
    return jsonEncode(style);
  }

  Map<String, Object?> _withStatePaint(Map<String, Object?> styleLayer) {
    final values = _statePaint(styleLayer);
    if (values.isEmpty) {
      return styleLayer;
    }
    final paint = styleLayer['paint'] == null ? <String, Object?>{} : _object(styleLayer['paint'], 'The paint of map style layer ${styleLayer['id']}');
    return {
      ...styleLayer,
      'paint': {...paint, ...values},
    };
  }

  /// *styleLayer* shown or hidden as the layer drawing its source is; unchanged for any other.
  Map<String, Object?> _withVisibility(Map<String, Object?> styleLayer) {
    final visible = _visibleOf(styleLayer);
    if (visible == null) {
      return styleLayer;
    }
    final layout = styleLayer['layout'] == null ? <String, Object?>{} : _object(styleLayer['layout'], 'The layout of map style layer ${styleLayer['id']}');
    return {
      ...styleLayer,
      'layout': {...layout, 'visibility': visible ? 'visible' : 'none'},
    };
  }

  /// *styleLayer* drawn with its own filter and the member filter of the layer drawing its source (`Map.filter`).
  Map<String, Object?> _withFilter(Map<String, Object?> styleLayer) {
    final filter = _filterOf(styleLayer);
    return filter == null ? styleLayer : {...styleLayer, 'filter': filter};
  }

  /// The filter *styleLayer* is drawn with: the document's own (its geometry
  /// filter) with the member filter of the layer drawing its source; `null`
  /// for a style layer no layer of this map draws, which keeps the document's.
  List<Object?>? _filterOf(Map<String, Object?> styleLayer) {
    final source = styleLayer['source'];
    if (source is! String || _layerNamed(source) == null) {
      return null;
    }
    final base = styleLayer['filter'];
    if (base is! List) {
      throw StateError('Map style layer ${styleLayer['id']} carries no filter; every generated style layer of a map layer has its geometry filter.');
    }
    return cruftfreeFiltered(List<Object?>.of(base), widget.handle?.memberFilter(source));
  }

  /// Whether the layer drawing *styleLayer*'s source is shown; `null` when no layer of this map draws it.
  bool? _visibleOf(Map<String, Object?> styleLayer) {
    final source = styleLayer['source'];
    return source is String ? _layerNamed(source)?.visible : null;
  }

  /// Each state paint of *styleLayer* with the value the layer or overlay drawing its source passes for the member.
  Map<String, Object> _statePaint(Map<String, Object?> styleLayer) {
    final named = _statePaintOf(styleLayer);
    if (named.isEmpty) {
      return const <String, Object>{};
    }
    final source = styleLayer['source'];
    final painter = switch (source) {
      final String name => switch ((_layerNamed(name), _overlayNamed(name))) {
        (final layer?, _) => (name: layer.name, state: layer.state),
        (null, final overlay?) => (name: overlay.name, state: overlay.state),
        (null, null) => null,
      },
      _ => null,
    };
    if (painter == null) {
      throw StateError('Map style layer ${styleLayer['id']} paints from state but no layer or overlay of this map draws it.');
    }
    return named.map((property, member) {
      final value = painter.state[member];
      if (value == null) {
        throw StateError('Map item ${painter.name} paints $property from $member, which its view does not pass.');
      }
      return MapEntry(property, _paintValue(value, painter.name, member));
    });
  }

  List<Map<String, Object?>> _lineFeatures() => [
    for (final polyline in _polylines)
      {
        'type': 'Feature',
        'properties': <String, Object?>{},
        'geometry': {
          'type': 'LineString',
          'coordinates': [for (final point in polyline.points) point._position],
        },
      },
  ];

  /// Each ring as a polygon through the points its `ringPolygon` placed, which close on the first.
  List<Map<String, Object?>> _ringFeatures() => [
    for (final ring in _rings)
      {
        'type': 'Feature',
        'properties': <String, Object?>{},
        'geometry': {
          'type': 'Polygon',
          'coordinates': [
            [
              for (final point in ring.points) [point.longitude, point.latitude],
            ],
          ],
        },
      },
  ];

  /// The handle's sketch as one feature; none while it sketches nothing.
  List<Map<String, Object?>> _sketchFeatures() => [
    if (widget.handle?.sketched case final geometry?) {'type': 'Feature', 'properties': <String, Object?>{}, 'geometry': geometry},
  ];

  List<Map<String, Object?>> _markerFeatures() => [
    for (final (index, marker) in _markers.indexed)
      {
        'type': 'Feature',
        'properties': {_markerIndex: index},
        'geometry': {'type': 'Point', 'coordinates': marker.point._position},
      },
  ];

  @override
  void initState() {
    super.initState();
    widget.handle?.attach(this);
    HardwareKeyboard.instance.addHandler(_keyPressed);
    if (widget.placesPin) {
      _pin = CruftFreeMapPin(write: _pinPlaced, show: (_) => _showPin())..held(widget.pin);
    }
    final camera = widget.camera;
    if (camera == null) {
      return;
    }
    final signature = widget.cameraSignature;
    final write = widget.onCameraChanged;
    if (signature == null || write == null) {
      throw StateError('A map bound to a camera state member compares settled cameras by the app\'s cameraSignature and writes the member back; its view must pass both.');
    }
    _placed = camera;
    _settle = CruftFreeCameraSettle(
      delay: Duration(milliseconds: widget.settleDelayMs),
      signature: signature,
      held: _heldCamera,
      write: (settled) {
        _placed = settled;
        write(settled);
      },
    );
  }

  @override
  void dispose() {
    widget.handle?.detach(this);
    HardwareKeyboard.instance.removeHandler(_keyPressed);
    _controller?.onFeatureDrag.remove(_featureDragged);
    _controller?.onMapMouseMove.remove(_pointerMoved);
    _focus.dispose();
    _settle?.cancel();
    _settle = null;
    _basemapFetching = null;
    super.dispose();
  }

  @override
  void didUpdateWidget(CruftFreeMap oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A body write of the bound member moves the pin; the person's own write, handed back, does not.
    _pin?.held(widget.pin);
    if (!identical(oldWidget.handle, widget.handle)) {
      oldWidget.handle?.detach(this);
      widget.handle?.attach(this);
    } else {
      // The layers' features may be another value now: the handle counts them again.
      widget.handle?.drawn(this);
    }
    // A popup shows a feature of the value its layer held when tapped: once the layer is gone or
    // holds another value, that feature is no longer drawn, so the popup closes.
    final open = _popups.shown;
    if (open != null && !identical(_layerNamed(open.layer)?.items, open.items)) {
      _popups.close();
    }
    // An overlay drawn inside another area now: its source's bounds change, so the style is set again.
    if (_shownBounds != null && jsonEncode(_overlayBounds(_document)) != _shownBounds) {
      _showPreferred();
    }
    if (_styleLoaded) {
      unawaited(_draw());
    }
  }

  /// `Map.fit`: moves the camera so it shows *bounds*.
  @override
  void fit(GeoBounds bounds) {
    final controller = _controller;
    if (controller == null) {
      return;
    }
    final shown = maplibre.LatLngBounds(southwest: maplibre.LatLng(bounds.minLat, bounds.minLon), northeast: maplibre.LatLng(bounds.maxLat, bounds.maxLon));
    unawaited(controller.animateCamera(maplibre.CameraUpdate.newLatLngBounds(shown, left: _fitPadding, top: _fitPadding, right: _fitPadding, bottom: _fitPadding)));
  }

  /// `Map.flyTo`: flies the camera to *point* at *zoom*.
  @override
  void flyTo(GeoPoint point, num zoom) {
    final controller = _controller;
    if (controller == null) {
      return;
    }
    unawaited(controller.animateCamera(maplibre.CameraUpdate.newLatLngZoom(maplibre.LatLng(point.latitude, point.longitude), zoom.toDouble())));
  }

  @override
  double? zoomLevel() => _zoom;

  @override
  List<String>? layerGeometryTypes(String layer) => _layerNamed(layer)?.geometryTypes;

  @override
  String? schemeShown() => _brightness?.name;

  /// The handle's sketch changed: feed it to the sketch source, once the style is shown.
  @override
  void sketched() {
    final controller = _controller;
    if (controller != null && _styleLoaded && mounted) {
      unawaited(controller.setGeoJsonSource(_sketchSource, _featureCollection(_sketchFeatures())));
    }
  }

  void _created(maplibre.MapLibreMapController controller) {
    _controller = controller;
    if (_pin != null) {
      controller.onFeatureDrag.add(_featureDragged);
    }
    controller.onMapMouseMove.add(_pointerMoved);
    _CruftFreeTileCredential.shared.attach(controller, _credentialCarried);
  }

  /// The engine carries the session's token now: the style shown is set again whole, so a tile
  /// its first requests asked for without the token is asked for again with it.
  void _credentialCarried() {
    final controller = _controller;
    final style = _shownStyle;
    if (!mounted || controller == null || style == null) {
      return;
    }
    _styleLoaded = false;
    unawaited(controller.setStyle(style));
  }

  // The engine is still alive while its map is deactivated (it is disposed before the map is), so
  // the map leaves the tile credential here, and takes it again when it is put back.
  @override
  void deactivate() {
    final controller = _controller;
    if (controller != null) {
      _CruftFreeTileCredential.shared.detach(controller);
    }
    super.deactivate();
  }

  @override
  void activate() {
    super.activate();
    final controller = _controller;
    if (controller != null) {
      _CruftFreeTileCredential.shared.attach(controller, _credentialCarried);
    }
  }

  /// The pointer moved over the map: the pointer handlers run with the point under it.
  void _pointerMoved(Point<double> point, maplibre.LatLng coordinates) {
    if (mounted) {
      widget.handle?.handlers.fire(CruftFreeMapEvent.onPointer, GeoPoint(latitude: coordinates.latitude, longitude: coordinates.longitude));
    }
  }

  /// A key pressed while the map has focus: the key handlers run with its name, and it goes no further when one heard it.
  KeyEventResult _mapKey(FocusNode node, KeyEvent event) {
    final handlers = widget.handle?.handlers;
    if (event is! KeyDownEvent || handlers == null || !handlers.listens(CruftFreeMapEvent.onKey)) {
      return KeyEventResult.ignored;
    }
    handlers.fire(CruftFreeMapEvent.onKey, cruftfreeMapKeyName(event));
    return KeyEventResult.handled;
  }

  /// Whether a tap at *point* is the second of a double tap: the last tap landed within the
  /// framework's double-tap time and distance of it. A double tap's second tap starts no other.
  bool _secondTap(Point<double> point) {
    final scale = Theme.of(context).platform == TargetPlatform.android ? MediaQuery.devicePixelRatioOf(context) : 1.0;
    final now = _tapClock.elapsed;
    final last = _lastTap;
    if (last != null && now - last.at <= kDoubleTapTimeout && (point - last.point).magnitude / scale <= kDoubleTapSlop) {
      _lastTap = null;
      return true;
    }
    _lastTap = (at: now, point: point);
    return false;
  }

  void _styleLoadedNow() {
    _styleLoaded = true;
    // A style load makes the engine's annotations anew, so the pin's circle is drawn again.
    _pinCircle = null;
    _showPin();
    unawaited(_drawAndReport());
  }

  /// The person wrote the member by placing the pin at *placed*: write it, then run `onChange`.
  void _pinPlaced(GeoPoint placed) {
    final write = widget.onPinChanged;
    if (write == null) {
      throw StateError('A map bound to a GeoPoint? member writes the member back; its view must pass onPinChanged.');
    }
    write(placed);
    widget.onChange?.call();
  }

  /// A drag of an annotation: the pin's moves it, and its end drops it.
  void _featureDragged(Point<double> point, maplibre.LatLng origin, maplibre.LatLng current, maplibre.LatLng delta, String id, maplibre.Annotation? annotation, maplibre.DragEventType eventType) {
    final pin = _pin;
    if (pin == null || !mounted || id != _pinCircle?.id) {
      return;
    }
    pin.dragged(GeoPoint(latitude: current.latitude, longitude: current.longitude));
    if (eventType == maplibre.DragEventType.end) {
      pin.dropped();
    }
  }

  /// Draw the pin where it stands, after any update of its circle still on its way to the engine.
  void _showPin() {
    _pinDrawing = _pinDrawing.then((_) => _drawPin());
  }

  /// The pin's circle placed where the pin stands, added for a pin newly placed and removed for none.
  Future<void> _drawPin() async {
    final controller = _controller;
    final pin = _pin;
    if (controller == null || pin == null || !_styleLoaded || !mounted) {
      return;
    }
    final point = pin.marker;
    final circle = _pinCircle;
    if (point == null) {
      if (circle != null) {
        _pinCircle = null;
        await controller.removeCircle(circle);
      }
      return;
    }
    final geometry = maplibre.LatLng(point.latitude, point.longitude);
    if (circle != null) {
      await controller.updateCircle(circle, maplibre.CircleOptions(geometry: geometry));
      return;
    }
    final colors = Theme.of(context).colorScheme;
    _pinCircle = await controller.addCircle(maplibre.CircleOptions(geometry: geometry, draggable: true, circleRadius: 10, circleColor: _hex(colors.primary), circleStrokeColor: _hex(colors.surface), circleStrokeWidth: 2));
  }

  /// Draw, then tell the handle naming this map the zoom the camera stands at.
  Future<void> _drawAndReport() async {
    await _draw();
    final controller = _controller;
    if (controller != null && mounted && widget.handle != null) {
      await _reportZoom(controller);
    }
  }

  MapCamera _heldCamera() {
    final camera = widget.camera;
    if (camera == null) {
      throw StateError('A map bound to a camera state member was handed no camera.');
    }
    return camera;
  }

  /// Read the zoom the camera stands at, and tell the handle naming this map.
  Future<void> _reportZoom(maplibre.MapLibreMapController controller) async {
    final position = await controller.queryCameraPosition();
    if (!mounted) {
      return;
    }
    _zoom = position?.zoom;
    widget.handle?.drawn(this);
  }

  /// The camera stopped moving: tell the handle naming this map its zoom, and
  /// hand where it stands to the settle rule of a map bound to a camera state member.
  Future<void> _cameraIdle() async {
    final controller = _controller;
    if (controller == null) {
      throw StateError('A map camera settled before its engine was created.');
    }
    if (widget.handle != null) {
      await _reportZoom(controller);
    }
    final settle = _settle;
    if (settle == null || !mounted) {
      return;
    }
    final position = controller.cameraPosition;
    if (position == null) {
      throw StateError('A map bound to a camera state member tracks its camera position, yet the engine reports none.');
    }
    final region = await controller.getVisibleRegion();
    if (!mounted) {
      return;
    }
    settle.settled(
      MapCamera(
        center: GeoPoint(latitude: position.target.latitude, longitude: position.target.longitude),
        zoom: position.zoom,
        bearing: position.bearing,
        pitch: position.tilt,
        bounds: GeoBounds(minLon: region.southwest.longitude, minLat: region.southwest.latitude, maxLon: region.northeast.longitude, maxLat: region.northeast.latitude),
      ),
    );
  }

  /// Move the map to the member's camera when it holds one the map does not stand at.
  Future<void> _followCamera(maplibre.MapLibreMapController controller, MapCamera camera) async {
    if (identical(camera, _placed)) {
      return;
    }
    _placed = camera;
    await controller.moveCamera(maplibre.CameraUpdate.newCameraPosition(_positionOf(camera)));
  }

  maplibre.CameraPosition _positionOf(MapCamera camera) => maplibre.CameraPosition(target: maplibre.LatLng(camera.center.latitude, camera.center.longitude), zoom: camera.zoom, bearing: camera.bearing, tilt: camera.pitch);

  /// Feed each layer's features, state paint and visibility, the lines and the
  /// markers to the shown style, and fit the camera to the markers and lines --
  /// or, for a map bound to a camera state member, stand where the member says.
  Future<void> _draw() async {
    final controller = _controller;
    if (controller == null) {
      throw StateError('A map style loaded before its engine was created.');
    }
    final document = _document;
    final documentSources = document == null ? const <String, Object?>{} : _object(document['sources'], 'A map style document\'s sources');
    for (final layer in _layers) {
      if (!documentSources.containsKey(layer.name)) {
        throw StateError('The map\'s style has no GeoJSON source ${layer.name}.');
      }
      await controller.setGeoJsonSource(layer.name, _featureCollection(layer.features));
    }
    if (document != null) {
      for (final styleLayer in document['layers'] as List) {
        final layer = _object(styleLayer, 'A map style layer');
        final values = _statePaint(layer);
        if (values.isNotEmpty) {
          await controller.setLayerProperties(layer['id'] as String, _StatePaint(values));
        }
        final visible = _visibleOf(layer);
        if (visible != null) {
          await controller.setLayerVisibility(layer['id'] as String, visible);
        }
        // `Map.filter`: the layer is drawn again from the features its source
        // holds -- no request is made.
        final filter = _filterOf(layer);
        if (filter != null) {
          await controller.setFilter(layer['id'] as String, filter);
        }
      }
    }
    await controller.setGeoJsonSource(_linesSource, _featureCollection(_lineFeatures()));
    await controller.setGeoJsonSource(_ringsSource, _featureCollection(_ringFeatures()));
    await controller.setGeoJsonSource(_sketchSource, _featureCollection(_sketchFeatures()));
    await controller.setGeoJsonSource(_markersSource, _featureCollection(_markerFeatures()));
    final camera = widget.camera;
    if (camera != null) {
      await _followCamera(controller, camera);
      return;
    }
    final markers = _markers;
    final polylines = _polylines;
    await _fit(controller, [
      for (final marker in markers) marker.point._latLng,
      for (final polyline in polylines)
        for (final point in polyline.points) point._latLng,
    ]);
  }

  Future<void> _fit(maplibre.MapLibreMapController controller, List<maplibre.LatLng> points) async {
    if (points.isEmpty) {
      final center = widget.center;
      await controller.moveCamera(center == null ? maplibre.CameraUpdate.newLatLngZoom(_worldCenter, _worldZoom) : maplibre.CameraUpdate.newLatLngZoom(center._latLng, widget.zoom?.toDouble() ?? _centerZoom));
      return;
    }
    final latitudes = [for (final point in points) point.latitude];
    final longitudes = [for (final point in points) point.longitude];
    final bounds = maplibre.LatLngBounds(southwest: maplibre.LatLng(latitudes.reduce(min), longitudes.reduce(min)), northeast: maplibre.LatLng(latitudes.reduce(max), longitudes.reduce(max)));
    await controller.moveCamera(maplibre.CameraUpdate.newLatLngBounds(bounds, left: _fitPadding, top: _fitPadding, right: _fitPadding, bottom: _fitPadding));
    final maxZoom = widget.zoom?.toDouble() ?? _fitZoom;
    final camera = await controller.queryCameraPosition();
    if (camera == null || camera.zoom > maxZoom) {
      await controller.moveCamera(maplibre.CameraUpdate.newLatLngZoom(camera?.target ?? bounds.southwest, maxZoom));
    }
  }

  /// A tap focuses the map and runs its click handlers with the tapped point
  /// (and its double-click handlers when it is a double tap's second), whatever
  /// it lands on. Then `hitTest(point, layers)`: a tap on a marker's pin
  /// activates the marker, as its list item does (the markers are drawn above
  /// every layer); else the tap reaches the layer `cruftfreeHitLayer` picks, whose
  /// `onClick` runs with the feature under the point and whose popup opens at it.
  Future<void> _tapped(Point<double> point, maplibre.LatLng coordinates) async {
    final controller = _controller;
    if (controller == null) {
      throw StateError('A map was tapped before its engine was created.');
    }
    _focus.requestFocus();
    final handlers = widget.handle?.handlers;
    if (handlers != null) {
      final tapped = GeoPoint(latitude: coordinates.latitude, longitude: coordinates.longitude);
      handlers.fire(CruftFreeMapEvent.onClick, tapped);
      if (_secondTap(point)) {
        handlers.fire(CruftFreeMapEvent.onDoubleClick, tapped);
      }
    }
    final markers = _markers;
    final features = await controller.queryRenderedFeatures(point, const [_markersSource], null);
    for (final feature in features) {
      final index = (feature as Map)['properties']?[_markerIndex];
      if (index is! num || index.toInt() >= markers.length) {
        throw StateError('A map marker feature carries no position in the map\'s markers: $feature');
      }
      markers[index.toInt()].onActivate?.call();
      return;
    }
    final hit = await cruftfreeHitLayer<CruftFreeMapLayer<Object?>, int>(_declaredLayers(), (layer) => _featureUnder(controller, point, layer));
    if (!mounted) {
      return;
    }
    if (hit == null) {
      _pin?.clicked(GeoPoint(latitude: coordinates.latitude, longitude: coordinates.longitude));
      return;
    }
    hit.layer.activateAt(hit.feature);
    if (hit.layer.hasPopup) {
      setState(() {
        _popups.open(_CruftFreeOpenPopup(layer: hit.layer.name, items: hit.layer.items, index: hit.feature, at: coordinates));
        _popupOffset = null;
      });
      await _placePopup();
    }
  }

  /// The map's layers in declared order: the order their style layers stand in the document.
  List<CruftFreeMapLayer<Object?>> _declaredLayers() {
    final ordered = <CruftFreeMapLayer<Object?>>[];
    final document = _document;
    if (document == null) {
      return ordered;
    }
    for (final styleLayer in document['layers'] as List) {
      final source = _object(styleLayer, 'A map style layer')['source'];
      final layer = source is String ? _layerNamed(source) : null;
      if (layer != null && !ordered.contains(layer)) {
        ordered.add(layer);
      }
    }
    return ordered;
  }

  /// The position, among *layer*'s items, of the feature it draws under *point*, or `null`. A
  /// drawn cluster stands for several features, so it is none of them; a hidden layer draws nothing.
  Future<int?> _featureUnder(maplibre.MapLibreMapController controller, Point<double> point, CruftFreeMapLayer<Object?> layer) async {
    final document = _document;
    if (document == null) {
      return null;
    }
    final ids = [
      for (final styleLayer in document['layers'] as List)
        if (_object(styleLayer, 'A map style layer') case {'source': final String source, 'id': final String id} when source == layer.name) id,
    ];
    if (ids.isEmpty) {
      return null;
    }
    for (final drawn in await controller.queryRenderedFeatures(point, ids, null)) {
      final properties = (drawn as Map)['properties'];
      if (properties is Map && properties['cluster'] == true) {
        continue;
      }
      final index = properties is Map ? properties[_featureIndex] : null;
      if (index is! num || index.toInt() >= layer.items.length) {
        throw StateError('A drawn feature of map layer ${layer.name} carries no position in its features: $drawn');
      }
      return index.toInt();
    }
    return null;
  }

  /// Place the popup shown at its feature's point as the camera now projects it. The engine
  /// answers in physical pixels on Android and in logical ones elsewhere.
  Future<void> _placePopup() async {
    final controller = _controller;
    final open = _popups.shown;
    if (controller == null || open == null) {
      return;
    }
    final screen = await controller.toScreenLocation(open.at);
    if (!mounted || !identical(_popups.shown, open)) {
      return;
    }
    final scale = Theme.of(context).platform == TargetPlatform.android ? MediaQuery.devicePixelRatioOf(context) : 1.0;
    setState(() => _popupOffset = Offset(screen.x / scale, screen.y / scale));
  }

  /// Escape, pressed anywhere, closes the popup shown.
  bool _keyPressed(KeyEvent event) {
    if (event is! KeyDownEvent || !mounted || !_popups.keyPressed(event.logicalKey)) {
      return false;
    }
    setState(() {});
    return true;
  }

  /// The popup shown, built from the feature its layer's binding loaded, or `null` until placed.
  Widget? _shownPopup() {
    final open = _popups.shown;
    final offset = _popupOffset;
    if (open == null || offset == null) {
      return null;
    }
    final layer = _layerNamed(open.layer);
    if (layer == null) {
      throw StateError('A map shows a popup of layer ${open.layer}, which it no longer draws.');
    }
    final tokens = CruftFreeTokens.of(context);
    return Positioned(
      left: offset.dx,
      top: offset.dy,
      child: FractionalTranslation(
        translation: const Offset(-0.5, -1),
        child: TapRegion(
          onTapOutside: (_) => setState(() => _popups.pressed(inside: false)),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: _popupMaxWidth),
            child: Semantics(
              liveRegion: true,
              child: Material(
                elevation: 4,
                borderRadius: BorderRadius.circular(tokens.radius),
                child: Padding(padding: EdgeInsets.all(tokens.inset), child: layer.popupAt(open.index)),
              ),
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final center = widget.center;
    final camera = widget.camera;
    final initialStyle = _initialStyle;
    final popups = _showsPopups;
    // Until the scheme's document has loaded from the app's bundle, the drawing keeps its place.
    Widget drawing = const SizedBox(height: _drawingHeight);
    if (initialStyle != null) {
      drawing = maplibre.MapLibreMap(
        styleString: initialStyle,
        initialCameraPosition: camera != null ? _positionOf(camera) : maplibre.CameraPosition(target: center?._latLng ?? _worldCenter, zoom: center == null ? _worldZoom : widget.zoom?.toDouble() ?? _centerZoom),
        trackCameraPosition: camera != null || popups,
        onCameraMove: popups ? (_) => unawaited(_placePopup()) : null,
        onCameraIdle: camera == null && widget.handle == null ? null : () => unawaited(_cameraIdle()),
        onMapCreated: _created,
        onStyleLoadedCallback: _styleLoadedNow,
        onMapClick: (point, coordinates) => unawaited(_tapped(point, coordinates)),
        // A double tap a handler hears is the handler's: the map does not also zoom.
        doubleClickZoomEnabled: widget.handle?.handlers.listens(CruftFreeMapEvent.onDoubleClick) == true ? false : null,
      );
    }
    final popup = _shownPopup();
    final map = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        SizedBox(
          height: _drawingHeight,
          child: Stack(
            children: [
              Positioned.fill(
                child: Focus(
                  focusNode: _focus,
                  onKeyEvent: _mapKey,
                  child: ExcludeSemantics(child: drawing),
                ),
              ),
              ?popup,
            ],
          ),
        ),
        for (final marker in _markers) ListTile(title: Text(marker.label), onTap: marker.onActivate),
      ],
    );
    return PopScope(
      canPop: _popups.shown == null,
      onPopInvokedWithResult: (didPop, _) {
        if (!didPop) {
          setState(() => _popups.back());
        }
      },
      child: cruftfreeStyled(context, widget.style, map),
    );
  }
}

/// The popup a map shows: the layer it belongs to, the value of the layer's binding it was
/// opened on and the feature's position in it, and the point tapped.
class _CruftFreeOpenPopup {
  const _CruftFreeOpenPopup({required this.layer, required this.items, required this.index, required this.at});

  final String layer;
  final List<Object?> items;
  final int index;
  final maplibre.LatLng at;
}
